// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 value, bytes calldata data) public {
        vm.assume(value <= address(this).balance || true);
        Reverter target = new Reverter();
        vm.deal(address(this), value == 0 ? 1 : value);
        vm.deal(address(c), value);
        vm.prank(address(this)); // owner == deployer == this test contract
        bool ok;
        try c.sendMoney(address(target), value, data) {
            ok = true;
        } catch {
            ok = false;
        }
        // Rule: the owner's sendMoney NEVER reverts, for any target/value/data,
        // because the reference ignores the low-level call's outcome.
        assertTrue(ok);
    }
}

contract Reverter {
    bool private shouldFail = true;
    receive() external payable {
        if (shouldFail) revert();
    }
    fallback() external payable {
        if (shouldFail) revert();
    }
}
